/**
 * Returns visual styling (color and SVG vector) for a given taxon.
 * Evaluates both iconic taxa and detailed insect/arachnid orders.
 */
export function getTaxonVisual(taxon?: InatTaxon | null): TaxonVisual {
  if (!taxon) {
    return {
      key: 'unknown',
      label: 'Neznámý',
      color: INAT_COLORS.gray,
      svgInner: SVG_ELEMENTS.unknown,
    };
  }

  // 1. Detailed orders (ancestor_ids or matched rank)
  const ancestors = taxon.ancestor_ids || [];
  const taxonName = (taxon.name || '').toLowerCase();
  const matchedRank = (taxon.rank || '').toLowerCase();

  // Coleoptera (Beetles)
  if (taxonName === 'coleoptera' || (matchedRank === 'order' && taxonName === 'coleoptera') || ancestors.includes(47208)) {
    return {
      key: 'coleoptera',
      label: 'Brouci (Coleoptera)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.coleoptera,
    };
  }

  // Lepidoptera (Butterflies & Moths)
  if (taxonName === 'lepidoptera' || (matchedRank === 'order' && taxonName === 'lepidoptera') || ancestors.includes(47157)) {
    return {
      key: 'lepidoptera',
      label: 'Motýli (Lepidoptera)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.lepidoptera,
    };
  }

  // Hymenoptera (Ants, Bees, Wasps)
  if (taxonName === 'hymenoptera' || (matchedRank === 'order' && taxonName === 'hymenoptera') || ancestors.includes(47201)) {
    return {
      key: 'hymenoptera',
      label: 'Blanokřídlí (Hymenoptera)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.hymenoptera,
    };
  }

  // Diptera (Flies, Mosquitoes)
  if (taxonName === 'diptera' || (matchedRank === 'order' && taxonName === 'diptera') || ancestors.includes(47822)) {
    return {
      key: 'diptera',
      label: 'Dvoukřídlí (Diptera)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.diptera,
    };
  }

  // Hemiptera (True bugs)
  if (taxonName === 'hemiptera' || (matchedRank === 'order' && taxonName === 'hemiptera') || ancestors.includes(47744)) {
    return {
      key: 'hemiptera',
      label: 'Polokřídlí (Hemiptera)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.hemiptera,
    };
  }

  // Odonata (Dragonflies & Damselflies)
  if (taxonName === 'odonata' || (matchedRank === 'order' && taxonName === 'odonata') || ancestors.includes(47792)) {
    return {
      key: 'odonata',
      label: 'Vážky (Odonata)',
      color: INAT_COLORS.orange,
      svgInner: SVG_ELEMENTS.odonata,
    };
  }

  // Araneae (Spiders)
  if (taxonName === 'araneae' || (matchedRank === 'order' && taxonName === 'araneae') || ancestors.includes(47118)) {
    return {
      key: 'araneae',
      label: 'Pavouci (Araneae)',
      color: INAT_COLORS.pink,
      svgInner: SVG_ELEMENTS.araneae,
    };
  }

  // 2. High-level Iconic Taxa
  const iconic = (taxon.iconic_taxon_name || '').toLowerCase();

  switch (iconic) {
    case 'plantae':
      return {
        key: 'plantae',
        label: 'Rostliny',
        color: INAT_COLORS.green,
        svgInner: SVG_ELEMENTS.plantae,
      };
    case 'insecta':
      return {
        key: 'insecta',
        label: 'Hmyz',
        color: INAT_COLORS.orange,
        svgInner: SVG_ELEMENTS.insecta,
      };
    case 'aves':
      return {
        key: 'aves',
        label: 'Ptáci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.aves,
      };
    case 'amphibia':
      return {
        key: 'amphibia',
        label: 'Obojživelníci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.amphibia,
      };
    case 'reptilia':
      return {
        key: 'reptilia',
        label: 'Plazi',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.reptilia,
      };
    case 'mammalia':
      return {
        key: 'mammalia',
        label: 'Savci',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.mammalia,
      };
    case 'actinopterygii':
      return {
        key: 'actinopterygii',
        label: 'Paprskoploutví',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.actinopterygii,
      };
    case 'mollusca':
      return {
        key: 'mollusca',
        label: 'Měkkýši',
        color: INAT_COLORS.pink,
        svgInner: SVG_ELEMENTS.mollusca,
      };
    case 'arachnida':
      return {
        key: 'arachnida',
        label: 'Pavoukovci',
        color: INAT_COLORS.pink,
        svgInner: SVG_ELEMENTS.arachnida,
      };
    case 'fungi':
      return {
        key: 'fungi',
        label: 'Houby',
        color: INAT_COLORS.purple,
        svgInner: SVG_ELEMENTS.fungi,
      };
    case 'chromista':
      return {
        key: 'chromista',
        label: 'Chromista',
        color: INAT_COLORS.brown,
        svgInner: SVG_ELEMENTS.chromista,
      };
    case 'protozoa':
      return {
        key: 'protozoa',
        label: 'Prvoci',
        color: INAT_COLORS.gray,
        svgInner: SVG_ELEMENTS.protozoa,
      };
    case 'animalia':
      return {
        key: 'animalia',
        label: 'Ostatní živočichové',
        color: INAT_COLORS.blue,
        svgInner: SVG_ELEMENTS.animalia,
      };
    default:
      return {
        key: 'unknown',
        label: 'Neznámý',
        color: INAT_COLORS.gray,
        svgInner: SVG_ELEMENTS.unknown,
      };
  }
}

/**
 * Compatible helper supporting both signature overloads:
 * getTaxonVisuals(taxon) or getTaxonVisuals(iconicTaxonName, taxon)
 */
export function getTaxonVisuals(
  iconicOrTaxon?: string | InatTaxon | null,
  taxon?: InatTaxon | null
): TaxonVisual {
  if (typeof iconicOrTaxon === 'string') {
    return getTaxonVisual(
      taxon || { id: 0, name: iconicOrTaxon, rank: '', iconic_taxon_name: iconicOrTaxon }
    );
  }
  return getTaxonVisual(iconicOrTaxon);
}

export function getAllTaxonVisuals(): TaxonVisual[] {
  const keys = Object.keys(SVG_ELEMENTS).filter(
    (k) => k !== 'star' && k !== 'comment' && k !== 'spark'
  );
  return keys.map((key) => {
    return getTaxonVisual({
      id: 0,
      name: key,
      rank: key.endsWith('a') || key === 'diptera' ? 'order' : 'class',
      iconic_taxon_name: key,
    });
  });
}
